head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.strCbd_SME_YN = "N^아님,Y^중소기업";
scwin.strCbd_HDCOM_YN = "N^관련없음,Y^지주회사";
scwin.strCbd_INVSTG_PROG_STAT_CD_1 = "01^심사진행,02^심사완료,03^심사완료(6개월경과등),04^심사연기,05^심사철회,06^심사기각";
scwin.strCbd_INVSTG_PROG_STAT_CD_2 = "10^신규상장 - 비상장,11^신규상장 - 코스닥법인,21^재상장 - 인적분할,22^재상장 - 폐지,23^재상장 - 합병,24^재상장 - 물적분할";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.rowPos;
scwin.mktTpCd; // 거래시장구분 1= 유가, 2=코스닥

// var gAfStdIndCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        await scwin.setComboCode();
        let parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.mktTpCd = parentWin.scwin.mktTpCd;
        scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정

        // alert("vBzProcsNo :"+vBzProcsNo);
        if (scwin.vBzProcsNo !== "") {
            // fn_initForm("");
            await scwin.readSync();
            cmb_SECUGRP_ID.setDisabled(true);
        } else {
            scwin.initForm("C");
            const sbmOptions = {
                id : "sbm_dts_Item",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Item=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Item.insertRow();
            cmb_SECUGRP_ID.setValue(parentWin.cmb_NEW_SECUGRP_ID.getValue());
            scwin.changeForm("01"); // 초기값-심사진행
            // chk_WEB_DP_YN.checked  = "N";

        }
        // alert( '[cmb_SECUGRP_ID]'+getObjectValue(cmb_SECUGRP_ID));

        scwin.initLabel(cmb_SECUGRP_ID.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function() {
    try {
        if (cmb_SECUGRP_ID.getValue() === "") {
            await $c.win.alert("[유가증권]을 선택하세요.");
            return;
        }
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindExamCorp(cmb_SECUGRP_ID.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003.img_COM_NM_onclick" });
    }
};

