/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        chk_WEB_DP_YN.setValue((dts_Item.getCellData(1, "WEB_DP_YN") === "N"));
        chk_WEB_NOPN_YN.setValue((dts_Item.getCellData(1, "WEB_NOPN_YN") === "Y"));
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            buttonSet.setUpdateStatus();
        }
        if (js_dep_cd !== '2520' && // 상장심사팀
            js_dep_cd !== '2540' && // 심사1팀,심사2팀
            js_dep_cd !== '2615') // 기업심사팀(2615) by nhkw

        {
            buttonSet.setErrorStatus(); // disable 시킨다.

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05003.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.readSync();
        scwin.parentRefresh();
        if (buttonSet.status === "U") {
            let parentWin = $c.frame.path("../");
            parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05003.trs_Save_OnSuccess" });
    }
};

