///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setComboCode
 * @description set Combo Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setComboCode = async function() {
    cmb_SME_YN.CBData = scwin.strCbd_SME_YN;
    cmb_HDCOM_YN.CBData = scwin.strCbd_HDCOM_YN;
    cmb_SME_YN.setSelectedIndex(0);
    cmb_HDCOM_YN.setSelectedIndex(0);

    // 주거래은행
    const sbmOptions = {
        id : "sbm_dts_MaintrBkCd",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_MaintrBkCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.elw.fn_searchCode();
};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    00443-통화ISO코드-일반사항-CURR_ISO_CD-cmb_CurrIsoCd
    00443-액면가통화ISO코드-일반사항-PARVAL_CURR_ISO_CD-cmb_ParvalCurrIsoCd
    00443-재무통화ISO코드-일반사항-FNC_CURR_ISO_CD-cmb_CapCurrIsoCd
    00443-공모가통화ISO코드-일반사항-PUBPRC_CURR_ISO_CD-cmb_PubprcCurrIsoCd
    00443-공모가예정통화ISO코드-일반사항-PUBPRC_SCHDL_CURR_ISO_CD-cmb_PubprcSchdlCurrIsoCd
    00685-명의개서대행기관-일반사항-TRANSSTK_AGNT_CD-cmb_TransstkAgntCd
    00755 - 외부감사인코드
     */
    const arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PARVAL_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_FNC_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PUBPRC_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_PUBPRC_SCHDL_CURR_ISO_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_NETINCM_CURR_ISO_CD"
    }, {
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "EXT_AUDTR_CD",
        cnm: "cmb_EXT_AUDTR_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        txb_COM_ENG_NM.setValue(arrPar[0].COM_ENG_NM);
        txb_CNTR_ISO_CD.alue = arrPar[0].CNTR_ISO_CD;
        txb_CNTR_ISO_NM.alue = arrPar[0].CNTR_ISO_NM;
        txb_HPAGE.setValue(arrPar[0].HPAGE);
        if (txb_ISUR_CD.getValue() !== "") {
            const sbmOptions = {
                id : "sbm_dts_Fias",
