/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[법인]을 선택하세요.");
        img_COM_NM.focus();
        return false;
    }
    if (txb_COM_NM.getValue() === "") {
        await $c.win.alert("[한글법인명]을 입력하세요..");
        txb_COM_NM.focus();
        return false;
    }

    // 2009.05.12 예비심사처리절차 등록 여부
    const cnt = dts_Item.getCellData(1, "STAT_CNT");
    // alert("[STAT_CNT] :"+dts_Item.NameValue(1,"STAT_CNT"));
    if (cnt === "0") {
        await $c.win.alert("예비심사절차등록이 누락되었습니다. 절차등록을 해주시기 바랍니다.");
        return false;
    }

    // 2009.05.12 법인명의 '주식회사' 를 '(주)'로 변경, '(주)'가 없는 법인인 경우 입력하도록..(국내법인인 경우만)
    if (dts_Item.getCellData(1, "SECUGRP_ID") === "ST") {
        // alert("[SECUGRP_ID] :"+dts_Item.NameValue(1,"SECUGRP_ID"));
        let tmpComNm_pre = txb_COM_NM.getValue();
        let tmpComNm_next = tmpComNm_pre.replace('주식회사', '');
        if (tmpComNm_pre !== tmpComNm_next) {
            await $c.win.alert("한글회사명에 '주식회사'는 '(주)'로 입력, 영문회사명에 'CO.,LTD' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
        tmpComNm_pre = txb_COM_NM.getValue();
        tmpComNm_next = tmpComNm_pre.replace('(주)', '');
        if (tmpComNm_pre === tmpComNm_next) {
            await $c.win.alert("한글회사명에 '(주)' 를 입력하세요");
            txb_COM_NM.focus();
            return false;
        }
    }
    if (txb_COM_ENG_NM.getValue() === "") {
        await $c.win.alert("[영문법인명]을 입력하세요..");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if (chk_WEB_DP_YN.checked && chk_WEB_NOPN_YN.checked) {
        await $c.win.alert("[비공개 심사시 선택] 와 [비공개(인적분할 재상시)]를 중복으로 선택하실수 없습니다.");
        chk_WEB_DP_YN.focus();
        return false;
    }
    if (edt_INVSTG_BILL_ACPT_DD.getValue() === "") {
        await $c.win.alert("[청구서접수일]를 입력하세요.");
        edt_INVSTG_BILL_ACPT_DD.focus();
        return false;
    }
    if (cmb_INVSTG_PROG_STAT_CD.getValue() === "02" && edt_INVSTG_COMPLT_DD.getValue() === "") {
        await $c.win.alert("[심사결과확정일]을 선택하십시오. \n상장구분이 심사완료인 경우 등록필수항목입니다.");
        edt_INVSTG_COMPLT_DD.focus();
        return false;
    }
    if (cmb_INVSTG_PROG_STAT_CD.getValue() === "") {
        await $c.win.alert("[심사상태]을 선택하세요.");
        cmb_INVSTG_PROG_STAT_CD.focus();
        return false;
    }

    // alert("[parseInt(txb_LIST_SHRS.value,10)."+parseInt(txb_LIST_SHRS.value,10));
    if (parseInt(edt_LIST_SHRS.getValue(), 10) <= 0 || edt_LIST_SHRS.getValue().length === 0) {
        await $c.win.alert("[상장(예정)주식수]를 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    if (dts_Item.getCellData(1, "SECUGRP_ID") === "FS") {
        if (edt_NETINCM_AMT.getValue().length === 0) {
            await $c.win.alert("[당기순이익(원화)]를 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
        if (edt_NETINCM_AMT1.getValue().length === 0) {
            await $c.win.alert("[당기순이익(외화)]를 입력하세요.");
            edt_NETINCM_AMT1.focus();
            return false;
        }
        // 통화 필수체크
        if (cmb_PARVAL_CURR_ISO_CD.getValue() === "") {
            await $c.win.alert("[액면가 통화표시]를 입력하세요.");
            cmb_PARVAL_CURR_ISO_CD.focus();
            return false;
        }
        if (cmb_FNC_CURR_ISO_CD.getValue() === "") {
            await $c.win.alert("[재무 통화표시]를 입력하세요.");
            cmb_FNC_CURR_ISO_CD.focus();
            return false;
        }
        if (cmb_PUBPRC_CURR_ISO_CD.getValue() === "") {
            await $c.win.alert("[공모가 통화표시]를 입력하세요.");
            cmb_PUBPRC_CURR_ISO_CD.focus();
            return false;
        }
        if (cmb_PUBPRC_SCHDL_CURR_ISO_CD.getValue() === "") {
            await $c.win.alert("[공모예정가 통화표시]를 입력하세요.");
            cmb_PUBPRC_SCHDL_CURR_ISO_CD.focus();
            return false;
        }
        if (cmb_NETINCM_CURR_ISO_CD.getValue() === "") {
            await $c.win.alert("[당기순이익(외화) 통화표시]를 입력하세요.");
            cmb_NETINCM_CURR_ISO_CD.focus();
            return false;
        }
    } else {
        if (edt_NETINCM_AMT.getValue().length === 0) {
            await $c.win.alert("[당기순이익]을 입력하세요.");
            edt_NETINCM_AMT.focus();
            return false;
        }
    }
    if (txb_CNTR_ISO_NM.getValue() === "410") {
        if (parseInt(edt_PARVAL.getValue(), 18) <= 0 || edt_PARVAL.getValue().length === 0) {
            await $c.win.alert("[액면가]를 입력하세요.");
            edt_PARVAL.focus();
            return false;
        }
    }

    // 2009.05.12 업종 및 주요제품을 필수로 처리
    if (txb_STD_IND_NM.getValue() === "") {
        await $c.win.alert("업종을 선택해주세요");
        txb_STD_IND_NM.focus();
        return false;
    }
    if (txb_MAJ_PROD_NM.getValue() === "") {
        await $c.win.alert("주요제품을 입력하세요");
        txb_MAJ_PROD_NM.focus();
        return false;
    }

    /*
    		if (getObjectValue(edt_SUBS_STRT_DD)== "") {
    			alert("[청약개시일]를 입력하세요.");edt_SUBS_STRT_DD.focus();return false;
    		}
    		if (getObjectValue(edt_SUBS_END_DD)== "") {
    			alert("[청약종료일]를 입력하세요.");edt_SUBS_END_DD.focus();return false;
    		}
    		if (parseInt(edt_SUBS_STRT_DD.Text, 10) >= parseInt(edt_SUBS_END_DD.Text, 10) ) {
    			alert("[청약개시일]은 [청약종료일]보다 작아야 합니다. 다시 입력해주세요");return false;
