     */
    return true;
    // alert(trs_Save.text);
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/
            X = TB_JOB_INSERT;
            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            // alert("BZ_PROCS_NO>>>>>>>> :"+dts_Item.NameValue(1,"BZ_PROCS_NO"));

            await scwin.trs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        await scwin.trs();
    }
};

