 */
scwin.prepare = async function() {
    let url = "/lstproc/ULDSTF05237.gfm?BZ_PROCS_NO=" + scwin.vBzProcsNo;
    await $c.frame.CreateDialogFrame("DLG_PREEXAM", url, "예비심사관리 절차등록", 0, 0, 625, 780, "window");
};

