/**
 * @method
 * @name getParDtl
 * @description get Par Dtl 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParDtl = function(arrPar) {
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = scwin.vBzProcsNo;
    arrPar[2] = txb_COM_NM.getValue();
};

/**
 * @method
 * @name openInvRst
 * @description open Inv Rst 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInvRst = async function() {
    scwin.fn_GetPar = scwin.getParDtl;
    scwin.fn_SetPar = undefined;
    const options = {
        id: "ULDSTF05010_STK",
        title: "위원회결과",
        type: "browserPopup",
        width: 545 + 10,
        height: 470 + 20,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../lstproc/ULDSTF05010_STK.gfm", options);
};
